// 候選碎片去重、合併多條碎裂途徑並排序。
// 來源：legacy fragmentScoring.ts
import type { FragmentCandidate } from '../types';

export interface MergedCandidate extends FragmentCandidate {
  mechanismList: string[];
  ruleList: string[];
  evidenceCount: number;
}

/**
 * Deduplicates fragment candidates by (formula + polarity + rounded m/z).
 * If a fragment is generated by multiple independent pathways (e.g. direct ester heterolysis and neutral loss),
 * it merges the mechanisms, retains the highest-fidelity charged RDKit ion representation, and boosts its score/confidence.
 */
export function deduplicateAndRankCandidates(
  candidates: FragmentCandidate[]
): FragmentCandidate[] {
  const map = new Map<string, MergedCandidate>();

  for (const c of candidates) {
    // Unique key by polarity, formula, and m/z (within 0.01 Da)
    const key = `${c.polarity}_${c.formula}_${c.mz.toFixed(2)}`;

    if (!map.has(key)) {
      map.set(key, {
        ...c,
        mechanismList: [c.mechanism],
        ruleList: [c.sourceRule],
        evidenceCount: 1,
        heuristicScore: c.heuristicScore ?? 50
      });
    } else {
      const existing = map.get(key)!;
      if (!existing.mechanismList.includes(c.mechanism)) {
        existing.mechanismList.push(c.mechanism);
      }
      if (!existing.ruleList.includes(c.sourceRule)) {
        existing.ruleList.push(c.sourceRule);
      }
      existing.evidenceCount += 1;

      // Prefer charged SMILES representation if the new candidate has an explicit formal charge in SMILES
      if (
        (c.smiles.includes('+') || c.smiles.includes('-')) &&
        !existing.smiles.includes('+') &&
        !existing.smiles.includes('-')
      ) {
        existing.smiles = c.smiles;
        existing.canonicalSmiles = c.canonicalSmiles || c.smiles;
        if (c.image) existing.image = c.image;
      }

      if (!existing.neutralLoss && c.neutralLoss) {
        existing.neutralLoss = c.neutralLoss;
        existing.neutralLossMass = c.neutralLossMass;
      }

      // Higher combined score for multi-pathway fragments
      const maxBase = Math.max(existing.heuristicScore || 50, c.heuristicScore || 50);
      existing.heuristicScore = Math.min(98, maxBase + 8);

      // Upgrade confidence and priority if multiple distinct mechanisms support it
      if (existing.confidence === 'Low') existing.confidence = 'Medium';
      else if (existing.confidence === 'Medium' && existing.evidenceCount >= 2) existing.confidence = 'High';

      if (existing.priority === 'Low') existing.priority = 'Medium';
      else if (existing.priority === 'Medium' && existing.evidenceCount >= 2) existing.priority = 'High';
    }
  }

  // Convert back to FragmentCandidate list with sorted ranking
  const mergedList: FragmentCandidate[] = Array.from(map.values()).map((item) => {
    let combinedMechanism = item.mechanismList.join('；以及 ');
    if (item.evidenceCount > 1) {
      combinedMechanism += ` (由 ${item.evidenceCount} 條獨立碎裂途徑共同支持)`;
    }

    const finalScore = Math.max(20, Math.min(98, item.heuristicScore || 50));

    return {
      id: item.id,
      technique: item.technique,
      polarity: item.polarity,
      precursorMz: item.precursorMz,
      mz: Number(item.mz.toFixed(4)),
      formula: item.formula,
      neutralFormula: item.neutralFormula,
      smiles: item.smiles,
      canonicalSmiles: item.canonicalSmiles || item.smiles,
      exactMass: Number(item.exactMass.toFixed(4)),
      neutralExactMass: Number((item.neutralExactMass ?? item.exactMass).toFixed(4)),
      ionExactMass: Number((item.ionExactMass ?? item.mz).toFixed(4)),
      charge: item.charge ?? (item.polarity === 'Negative' ? -1 : 1),
      ionType: item.ionType,
      mechanism: combinedMechanism,
      fragmentationPathway: item.fragmentationPathway,
      pathwayStatus: item.pathwayStatus || 'Verified Graph Product',
      neutralLoss: item.neutralLoss,
      neutralLossMass: item.neutralLossMass,
      massBalanceError: item.massBalanceError,
      massBalanceVerified: item.massBalanceVerified ?? true,
      parentStructureId: item.parentStructureId,
      priority: item.priority,
      confidence: item.confidence,
      sourceRule: item.ruleList.join(', '),
      heuristicScore: Number(finalScore.toFixed(1)),
      image: item.image,
      explanation: item.explanation,
      parameterContext: item.parameterContext
    };
  });

  // Sort: High priority first, then descending heuristic score
  return mergedList.sort((a, b) => {
    const priorityWeight: Record<string, number> = { High: 3, Medium: 2, Low: 1 };
    const pDiff = (priorityWeight[b.priority] || 1) - (priorityWeight[a.priority] || 1);
    if (pDiff !== 0) return pDiff;
    return (b.heuristicScore || 0) - (a.heuristicScore || 0);
  });
}
